def capture_click_through(sim_html, reel_dir, *,
        selector, hold_each, out_name, ...):
    ...
    page.goto(url, wait_until='networkidle', timeout=30_000)
    time.sleep(1.5)

    # Guard: silent miss IS the bug
    count = page.evaluate(
        'sel => document.querySelectorAll(sel).length', selector)
    if count < 2:
        raise RuntimeError(
          f"[capture_sim] --click-through '{selector}' "
          f"matched {count} element(s); need >= 2. A single-"
          f"element selector silently produces a static clip.")

    time.sleep(1.0)                     # hold before first click
    for i in range(count):
        # Re-query — live DOM mutations invalidate old handles
        page.evaluate('''([sel, idx]) => {
            const el = document.querySelectorAll(sel)[idx];
            if (!el) return;
            el.click();
        }''', [selector, i])
        settle_deadline = time.monotonic() + min(0.8, hold_each*0.3)
        while time.monotonic() < settle_deadline: time.sleep(0.05)
        time.sleep(max(0.0, hold_each - min(0.8, hold_each*0.3)))
    time.sleep(0.5)                     # tail hold
